'use strict';

// Bundle MWT Markdown engineering docs into a JS map so mwt/index.html works over file:// as well as HTTP/HTTPS.
const fs = require('node:fs');
const path = require('node:path');

const mwtDir = path.join(__dirname, '..', 'mwt');
const files = [
  'MWTP_50C_Split_Power_Design.md',
  'MWTP_50_Restaurant_Compact_Unit_Design.md',
  'MWTP_250_Engineering_Design_Package.md',
  'MWTP_250_PID_and_Valve_Matrix.md',
  'MWTP_250_BOM_and_Cost_Breakdown.md',
  'MWTP_250_Hospital_Restaurant_Tie_In_SOP.md',
  'MWTP_250_Bank_Loan_Business_Plan.md'
];

const bundle = {};
for (const file of files) {
  const fullPath = path.join(mwtDir, file);
  if (fs.existsSync(fullPath)) {
    bundle[file] = fs.readFileSync(fullPath, 'utf8');
  }
}

const outPath = path.join(mwtDir, 'docs-bundle.js');
const content = `// Auto-generated by scripts/build-mwt-docs-bundle.js for offline/file:// fallback.\nwindow.MWT_DOCS_BUNDLE = ${JSON.stringify(bundle)};\n`;
fs.writeFileSync(outPath, content, 'utf8');
console.log(`Built ${outPath} (${Object.keys(bundle).length} docs)`);
